import './styles.css';
import { openDatabase } from './core/database/indexed-db.js';
import { calculateAccountBalances, summarizeTransactions, sumSafeIntegers, formatRupiah } from './core/finance/ledger.js';
import { DEFAULT_CATEGORIES, getAvailableCategories, validateCategory, archiveCategory, restoreCategory } from './core/finance/categories.js';

const $ = (s, r=document) => r.querySelector(s);
const view=$('#view'), modal=$('#modal'), modalContent=$('#modal-content'), toastNode=$('#toast');
let db, page='home', accounts=[], transactions=[], categories=[], budgets=[], settings={theme:'system',language:'id'}, toastTimer;
let lockedPageScrollY=0, pageScrollLocked=false, pickerCloseTimer=null;
function lockPageScroll(){if(pageScrollLocked)return;lockedPageScrollY=window.scrollY||document.documentElement.scrollTop||0;pageScrollLocked=true;document.body.style.position='fixed';document.body.style.top=`-${lockedPageScrollY}px`;document.body.style.left='0';document.body.style.right='0';document.body.style.width='100%';document.body.style.overflow='hidden';}
function unlockPageScroll(){if(!pageScrollLocked)return;document.body.style.position='';document.body.style.top='';document.body.style.left='';document.body.style.right='';document.body.style.width='';document.body.style.overflow='';window.scrollTo(0,lockedPageScrollY);pageScrollLocked=false;}
const today=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)};
const isValidDate=v=>{if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const [y,m,d]=v.split('-').map(Number),date=new Date(Date.UTC(y,m-1,d));return date.getUTCFullYear()===y&&date.getUTCMonth()===m-1&&date.getUTCDate()===d};
const uid=()=>crypto.randomUUID();
const money=n=>formatRupiah(n);
const monthKey=()=>today().slice(0,7);
const accountMap=()=>new Map(accounts.map(a=>[a.id,a]));
const balances=()=>calculateAccountBalances(accounts,transactions);
const monthTransactions=()=>transactions.filter(t=>(t.transactionDate||'').startsWith(monthKey()));
const tr=(id)=>transactions.find(t=>t.id===id);

const ico=(name,size=20)=>{const paths={plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',income:'<path d="M7 17 17 7M7 7h10v10"/>',expense:'<path d="M7 7 17 17M7 17h10V7"/>',transfer:'<path d="M4 8h15m-4-4 4 4-4 4M20 16H5m4-4-4 4 4 4"/>',wallet:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 9h18m-5 5h2"/>',cash:'<rect x="3" y="6" width="18" height="12" rx="2"/><circle cx="12" cy="12" r="3"/>',bank:'<path d="m3 9 9-6 9 6M5 10v8m4-8v8m6-8v8m4-8v8M3 21h18M2 18h20"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',tag:'<path d="M20 13 13 20 3 10V4h6z"/><circle cx="7.5" cy="8" r="1"/>',check:'<path d="m5 12 4 4L19 6"/>',file:'<path d="M6 3h8l4 4v14H6zM14 3v5h5M9 13h6M9 17h6"/>',utensils:'<path d="M7 2v8m-3-8v5a3 3 0 0 0 6 0V2M7 10v12m10-20v20m0-20c-3 3-3 8 0 9"/>',car:'<path d="m5 11 2-5h10l2 5m2 0H3v8h18zM6 19v2m12-2v2M6 15h.01M18 15h.01"/>',shopping:'<path d="M5 8h14l1 13H4L5 8Zm3 0a4 4 0 0 1 8 0"/>',receipt:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3Zm3 5h6m-6 4h6m-6 4h3"/>',health:'<path d="M12 21s-8-4.5-8-11a4.5 4.5 0 0 1 8-2.8A4.5 4.5 0 0 1 20 10c0 6.5-8 11-8 11Z"/><path d="M8 12h8m-4-4v8"/>',education:'<path d="m2 9 10-5 10 5-10 5L2 9Zm4 3v5c4 3 8 3 12 0v-5m4-3v7"/>',entertainment:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m10 9 5 3-5 3z"/>',house:'<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>',gift:'<rect x="3" y="9" width="18" height="12" rx="2"/><path d="M2 9h20M12 9v12m0-12H8a2.5 2.5 0 1 1 2.5-2.5L12 9Zm0 0h4a2.5 2.5 0 1 0-2.5-2.5L12 9Z"/>',sparkles:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3Z"/>',wallet:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 9h18m-5 5h2"/>'};paths['shopping-bag']=paths.shopping;paths['heart-pulse']=paths.health;paths['graduation-cap']=paths.education;paths.clapperboard=paths.entertainment;paths['hand-coins']=paths.cash;paths['briefcase-business']=paths.bank;paths.ellipsis=paths.tag;return '<svg class="ui-icon" width="'+size+'" height="'+size+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||paths.tag)+'</svg>'};

const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateFmt=v=>v?new Intl.DateTimeFormat(settings.language==='en'?'en-US':'id-ID',{day:'numeric',month:'short',year:'numeric'}).format(new Date(v+'T00:00:00')):'—';
const monthFmt=v=>new Intl.DateTimeFormat(settings.language==='en'?'en-US':'id-ID',{month:'long',year:'numeric'}).format(new Date(v+'-01T00:00:00'));
const labels={id:{home:'Beranda',history:'Riwayat',wallets:'Dompet',stats:'Statistik',balance:'Total saldo',income:'Pemasukan',expense:'Pengeluaran',recent:'Transaksi terbaru',all:'Lihat semua',add:'Tambah transaksi',empty:'Belum ada transaksi',emptyHint:'Catatan keuanganmu akan muncul di sini.',save:'Simpan',cancel:'Batal',settings:'Pengaturan',budgets:'Anggaran',categories:'Kategori',search:'Cari transaksi atau kategori'},en:{home:'Home',history:'History',wallets:'Wallets',stats:'Statistics',balance:'Total balance',income:'Income',expense:'Expenses',recent:'Recent transactions',all:'See all',add:'Add transaction',empty:'No transactions yet',emptyHint:'Your financial activity will appear here.',save:'Save',cancel:'Cancel',settings:'Settings',budgets:'Budgets',categories:'Categories',search:'Search transactions or categories'}};
const L=k=>labels[settings.language]?.[k]||labels.id[k]||k;
function req(r){return new Promise((ok,no)=>{r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error||new Error('Permintaan database gagal.'))})}
function store(name,mode='readonly'){return db.transaction(name,mode).objectStore(name)}
function transactionDone(tx){return new Promise((ok,no)=>{tx.oncomplete=()=>ok();tx.onerror=()=>no(tx.error||new Error('Transaksi database gagal.'));tx.onabort=()=>no(tx.error||new Error('Transaksi database dibatalkan.'))})}
async function all(name){return req(store(name).getAll())}
async function put(name,v){const t=db.transaction(name,'readwrite');t.objectStore(name).put(v);await transactionDone(t)}
async function remove(name,key){const t=db.transaction(name,'readwrite');t.objectStore(name).delete(key);await transactionDone(t)}
async function refresh(){[accounts,transactions,categories,budgets]=await Promise.all(['accounts','transactions','categories','budgets'].map(all));accounts.sort((a,b)=>a.name.localeCompare(b.name));transactions.sort((a,b)=>(b.transactionDate||'').localeCompare(a.transactionDate||'')||(b.createdAt||0)-(a.createdAt||0));render()}
function toast(msg){toastNode.textContent=msg;toastNode.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastNode.classList.remove('show'),2300)}
function empty(title=L('empty'),hint=L('emptyHint')){return `<div class="empty"><span class="empty-mark">${ico('file',22)}</span><strong>${esc(title)}</strong><p>${esc(hint)}</p></div>`}
function row(t){const a=accountMap(),inc=t.type==='income',transfer=t.type==='transfer';const title=transfer?`${a.get(t.accountId)?.name||'Dompet'} → ${a.get(t.destinationAccountId)?.name||'Dompet'}`:t.category|| (inc?'Pemasukan':'Pengeluaran');return `<button class="tx-row" data-action="edit-tx" data-id="${t.id}"><span class="tx-symbol ${t.type}">${ico(inc?'income':transfer?'transfer':'expense',19)}</span><span class="tx-copy"><b>${esc(title)}</b><small>${esc(t.note||a.get(t.accountId)?.name||'Tanpa catatan')} · ${dateFmt(t.transactionDate)}</small></span><strong class="tx-amount ${inc?'income-text':transfer?'':'expense-text'}">${inc?'+':transfer?'':'−'}${money(t.amount)}</strong></button>`}
function pageHead(k,title,sub=''){return `<header class="page-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div></header>`}
function render(){document.querySelectorAll('[data-page]').forEach(b=>{const current=b.dataset.page===page;b.classList.toggle('active',current);if(current)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(page==='home')home();if(page==='transactions')historyPage();if(page==='accounts')walletPage();if(page==='stats')statsPage()}
function home(){const s=summarizeTransactions(monthTransactions()),total=sumSafeIntegers([...balances().values()],'Total saldo seluruh dompet');view.innerHTML=`
<section class="balance-panel"><div class="balance-top"><span>${L('balance')}</span><button class="balance-toggle" data-action="toggle-balance" aria-label="Sembunyikan saldo">${ico('eye',18)}</button></div><strong id="balance-value">${money(total)}</strong><div class="balance-foot"><span>${accounts.length} dompet</span><span class="local-tag"><i></i> Tersimpan di perangkat</span></div></section>
<section class="cash-summary"><div><span class="metric-label"><i class="dot income-dot"></i>${L('income')} bulan ini</span><strong class="income-text">${money(s.income)}</strong></div><div><span class="metric-label"><i class="dot expense-dot"></i>${L('expense')} bulan ini</span><strong class="expense-text">${money(s.expense)}</strong></div></section>
<div class="quick-actions"><button data-action="new-tx" data-type="income"><span class="quick-sign plus">${ico('plus',19)}</span><span><b>Tambah pemasukan</b><small>Uang masuk</small></span></button><button data-action="new-tx" data-type="expense"><span class="quick-sign minus">${ico('minus',19)}</span><span><b>Tambah pengeluaran</b><small>Uang keluar</small></span></button></div>
<section class="section"><div class="section-title"><h3>${L('recent')}</h3><button class="text-link" data-page="transactions">${L('all')}</button></div><div class="transaction-list">${transactions.length?transactions.slice(0,5).map(row).join(''):empty()}</div></section>`}
function historyPage(){view.innerHTML=`${pageHead('','Riwayat') }<div class="search-box"><span>⌕</span><input id="tx-search" placeholder="${L('search')}" autocomplete="off"></div><div class="filter-strip"><button class="filter active" data-filter="all">Semua</button><button class="filter" data-filter="income">Masuk</button><button class="filter" data-filter="expense">Keluar</button><button class="filter" data-filter="transfer">Transfer</button></div><div class="filter-extra"><select id="wallet-filter"><option value="">Semua dompet</option>${accounts.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select><input id="date-filter" type="month" value="${monthKey()}"></div><div class="transaction-list" id="history-list">${transactions.length?transactions.map(row).join(''):empty()}</div>`}
function walletPage(){const b=balances();view.innerHTML=`${pageHead('','Dompet') }<div class="wallet-total"><span>Total seluruh dompet</span><strong>${money(sumSafeIntegers([...b.values()],'Total saldo seluruh dompet'))}</strong></div><div class="section-title wallet-heading"><h3>Daftar dompet</h3><button class="text-link" data-action="add-wallet">＋ Tambah</button></div><div class="wallet-list">${accounts.map(a=>`<article class="wallet-row"><span class="wallet-icon">${a.kind==='Bank'?'▤':a.kind==='E-wallet'?'▣':'◉'}</span><span class="wallet-copy"><b>${esc(a.name)}</b><small>${esc(a.kind||'Dompet')}</small></span><strong>${money(b.get(a.id)||0)}</strong><button class="more" data-action="wallet-menu" data-id="${a.id}" aria-label="Opsi dompet">···</button></article>`).join('')||empty('Belum ada dompet','Tambahkan dompet untuk mulai mencatat keuangan.')}</div><button class="secondary-button full" data-action="transfer">⇄ Transfer antar-dompet</button>`}
function budgetFor(categoryId){return budgets.find(b=>b.categoryId===categoryId&&b.period===monthKey())}
function budgetProgress(c){const budget=budgetFor(c.id);if(!budget)return null;const spent=sumSafeIntegers(monthTransactions().filter(t=>t.type==='expense'&&(t.categoryId===c.id||t.category===c.name)).map(t=>t.amount),'Total pengeluaran kategori');return {limit:budget.amount,spent,pct:budget.amount?spent/budget.amount*100:0}}
function statsPage(){const s=summarizeTransactions(monthTransactions()),max=Math.max(s.income,s.expense,1),expenseCats=getAvailableCategories(categories,'expense').map(c=>({...c,...(budgetProgress(c)||{})})).filter(c=>c.limit||c.spent);const activeBudgetIds=new Set(getAvailableCategories(categories,'expense').map(c=>c.id)),totalBudget=sumSafeIntegers(budgets.filter(b=>b.period===monthKey()&&activeBudgetIds.has(b.categoryId)).map(b=>b.amount),'Total anggaran'),spent=sumSafeIntegers(monthTransactions().filter(t=>t.type==='expense'&&activeBudgetIds.has(t.categoryId)&&budgets.some(b=>b.period===monthKey()&&b.categoryId===t.categoryId)).map(t=>t.amount),'Total realisasi anggaran'),budgetPct=totalBudget?spent/totalBudget*100:0,budgetState=budgetPct>=100?'over':budgetPct>=90?'warn':budgetPct>=70?'approach':'';view.innerHTML=`${pageHead('','Statistik',monthFmt(monthKey()))}<div class="stat-overview"><div><span>Arus bersih</span><strong class="${s.net>=0?'income-text':'expense-text'}">${money(s.net)}</strong></div><div class="stat-mini"><span>Masuk</span><b class="income-text">${money(s.income)}</b><span>Keluar</span><b class="expense-text">${money(s.expense)}</b></div></div><section class="section"><div class="section-title"><h3>Arus kas</h3></div><div class="chart-panel"><div class="bar-item"><div><span>Pemasukan</span><b class="income-text">${money(s.income)}</b></div><i><em class="income-bar" style="width:${s.income/max*100}%"></em></i></div><div class="bar-item"><div><span>Pengeluaran</span><b class="expense-text">${money(s.expense)}</b></div><i><em class="expense-bar" style="width:${s.expense/max*100}%"></em></i></div><small>Transfer tidak dihitung sebagai pemasukan atau pengeluaran.</small></div></section><section class="section"><div class="section-title"><div><h3>Anggaran kategori</h3><p>Periode ${monthFmt(monthKey())}</p></div><button class="text-link" data-action="manage-budgets">Kelola</button></div><div class="budget-summary"><div><span>Total anggaran</span><strong>${money(totalBudget)}</strong></div><div><span>Terpakai</span><strong>${money(spent)}</strong></div><div class="budget-track"><i class="${budgetState}" style="width:${totalBudget?Math.min(budgetPct,100):0}%"></i></div><small class="${budgetState==='over'?'expense-text':budgetState?'warning-text':''}">${totalBudget?Math.round(budgetPct)+'% digunakan · '+(budgetState==='over'?'Anggaran terlampaui':budgetState==='warn'?'Mendekati batas':budgetState==='approach'?'Perlu diperhatikan':'Dalam batas'):'Belum ada anggaran bulan ini'}</small></div>${expenseCats.length?expenseCats.map(c=>{const p=budgetProgress(c);if(!p)return '';const pct=p.pct;return `<div class="budget-row"><div><b>${esc(c.name)}</b><span>${money(p.spent)} / ${money(p.limit)}</span></div><i class="budget-track"><em class="${pct>=100?'over':pct>=90?'warn':''}" style="width:${Math.min(pct,100)}%"></em></i><small class="${pct>=100?'expense-text':pct>=90?'warning-text':'muted'}">${pct>=100?'Melebihi anggaran':pct>=90?'Hampir mencapai batas':pct>=70?'Mendekati batas':'Dalam batas'}</small></div>`}).join('') : empty('Belum ada anggaran','Tetapkan batas pengeluaran untuk kategori pilihanmu.')}</section>`}
function showPicker(type,target){const layer=$('#picker-layer'),f=$('#modal-form');let title='Pilih';let body='';if(type==='category'){title='Pilih kategori';const kind=f.querySelector('[name="type"]').value;body=getAvailableCategories(categories,kind).map(c=>`<button type="button" class="sheet-option ${f.querySelector('[name="categoryId"]').value===c.id?'selected':''}" data-picker-option="category" data-value="${c.id}"><span class="sheet-option-icon">${ico(c.icon||'tag',19)}</span><span>${esc(c.name)}</span><span class="sheet-check">${ico('check',18)}</span></button>`).join('')||'<p class="sheet-empty">Belum ada kategori.</p>'}else if(type==='wallet'){title=target==='destinationAccountId'?'Pilih dompet tujuan':'Pilih dompet';const current=f.querySelector(`[name="${target}"]`).value,other=target==='destinationAccountId'?f.querySelector('[name="accountId"]').value:f.querySelector('[name="destinationAccountId"]').value;body=accounts.filter(a=>a.id!==other).map(a=>`<button type="button" class="sheet-option wallet-option ${current===a.id?'selected':''}" data-picker-option="wallet" data-target="${target}" data-value="${a.id}"><span class="sheet-option-icon">${ico('wallet',18)}</span><span><b>${esc(a.name)}</b><small>${esc(a.kind||'Dompet')} · ${money(balances().get(a.id)||0)}</small></span><span class="sheet-check">✓</span></button>`).join('')||'<p class="sheet-empty">Tidak ada dompet lain yang bisa dipilih.</p>'}else if(type==='date'){title='Pilih tanggal transaksi';body=`<div class="sheet-date-wrap"><input id="sheet-date-value" type="date" value="${f.querySelector('[name="transactionDate"]').value}" max="9999-12-31"></div><button type="button" class="primary-button full" data-picker-apply="date">Gunakan tanggal</button>`}clearTimeout(pickerCloseTimer);pickerCloseTimer=null;layer.setAttribute('aria-label',title);layer.innerHTML=`<div class="picker-backdrop" data-picker-close></div><section class="picker-sheet" aria-label="${title}"><div class="sheet-grabber"></div><header class="sheet-header"><h3>${title}</h3><button type="button" class="sheet-close" data-picker-close aria-label="Tutup">×</button></header><div class="sheet-options">${body}</div></section>`;layer.dataset.dragY='0';layer.classList.remove('is-dragging');if(!layer.open)layer.showModal();requestAnimationFrame(()=>{layer.classList.add('visible');layer.querySelector('.sheet-close')?.focus({preventScroll:true})})}function closePicker(immediate=false){const layer=$('#picker-layer');if(!layer.open)return;clearTimeout(pickerCloseTimer);pickerCloseTimer=null;const panel=layer.querySelector('.picker-sheet');layer.classList.remove('visible');if(immediate){layer.close();layer.innerHTML='';return}let done=false;const finish=e=>{if(done)return;if(e&&((e.target!==panel)||e.propertyName!=='transform'))return;done=true;clearTimeout(pickerCloseTimer);pickerCloseTimer=null;if(layer.open)layer.close();layer.innerHTML='';panel?.removeEventListener('transitionend',finish)};panel?.addEventListener('transitionend',finish);pickerCloseTimer=setTimeout(()=>finish(),420)}function openModal(html,variant=''){lockPageScroll();modalContent.innerHTML=html;modal.classList.toggle('transaction-sheet',variant==='transaction-sheet');const heading=modalContent.querySelector('.modal-head h3');if(heading){heading.id='modal-dialog-title';modal.setAttribute('aria-labelledby',heading.id)}else modal.removeAttribute('aria-labelledby');const initialFocus=modalContent.querySelector('.close-modal');if(initialFocus)initialFocus.setAttribute('autofocus','');if(!modal.open)modal.showModal();if(initialFocus)initialFocus.focus({preventScroll:true})}
function closeModal(){closePicker(true);modal.close();modal.classList.remove('transaction-sheet')}
function footerButtons(label='Simpan'){return `<div class="modal-actions"><button type="button" class="secondary-button" data-action="close">${L('cancel')}</button><button class="primary-button" type="submit">${label}</button></div><p class="form-error" id="form-error" role="alert"></p>`}
function walletOptions(selected=''){return accounts.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${esc(a.name)}</option>`).join('')}
function categoryPicker(type,selectedId){const list=getAvailableCategories(categories,type),selected=categories.find(c=>c.id===selectedId&&c.type===type),name=list.find(c=>c.id===selectedId)?.name||(selected?.isArchived?selected.name+' (Diarsipkan)':'Pilih kategori');return `<div class="category-picker"><button type="button" class="picker-trigger" data-open-picker="category"><span class="picker-trigger-icon">${ico('tag',18)}</span><span id="category-picker-label">${esc(name)}</span><span class="picker-chevron">⌄</span></button><input type="hidden" name="categoryId" value="${selectedId||''}"><input type="hidden" name="category" value="${esc(selected?.name||'')}"></div>`}
function txForm(item=null,type='expense'){const t=item||{},kind=t.type||type,category=t.categoryId||categories.find(c=>c.type===kind&&!c.isArchived)?.id;openModal(`<div class="modal-head"><div><span class="overline">${item?'UBAH CATATAN':'TRANSAKSI BARU'}</span><h3>${item?'Edit transaksi':'Tambah transaksi'}</h3></div><button type="button" class="close-modal" data-action="close">×</button></div><div class="type-tabs">${['expense','income','transfer'].map(x=>`<button type="button" data-type-choice="${x}" class="${kind===x?'chosen':''}">${x==='expense'?'Keluar':x==='income'?'Masuk':'Transfer'}</button>`).join('')}</div><input type="hidden" name="type" value="${kind}"><label class="field amount-field"><span>Nominal (Rp)</span><input class="amount-input" name="amount" type="number" min="1" step="1" inputmode="numeric" placeholder="0" value="${t.amount??''}" required></label><div class="field picker-field"><span>Dompet ${kind==='transfer'?'asal':''}</span><button type="button" class="picker-trigger" data-open-picker="wallet" data-wallet-target="accountId"><span class="picker-trigger-icon">${ico('wallet',18)}</span><span id="wallet-accountId-label">${esc(accounts.find(a=>a.id===(t.accountId||accounts[0]?.id))?.name||'Pilih dompet')}</span><span class="picker-chevron">⌄</span></button><input type="hidden" name="accountId" value="${t.accountId||accounts[0]?.id||''}" required></div><div class="field destination-field picker-field" ${kind==='transfer'?'':'hidden'}><span>Dompet tujuan</span><button type="button" class="picker-trigger" data-open-picker="wallet" data-wallet-target="destinationAccountId"><span class="picker-trigger-icon">${ico('transfer',18)}</span><span id="wallet-destinationAccountId-label">${esc(accounts.find(a=>a.id===(kind==='transfer'?(t.destinationAccountId||accounts.find(x=>x.id!==(t.accountId||accounts[0]?.id))?.id):''))?.name||'Pilih dompet')}</span><span class="picker-chevron">⌄</span></button><input type="hidden" name="destinationAccountId" value="${kind==='transfer'?(t.destinationAccountId||accounts.find(a=>a.id!==(t.accountId||accounts[0]?.id))?.id||''):''}"></div><div class="field category-field" ${kind==='transfer'?'hidden':''}><span>Kategori</span>${categoryPicker(kind,category)}</div><div class="field date-field"><span>Tanggal transaksi</span><button type="button" class="picker-trigger" data-open-picker="date"><span class="picker-trigger-icon">${ico('calendar',18)}</span><span id="date-picker-label">${dateFmt(t.transactionDate||today())}</span><span class="picker-chevron">⌄</span></button><input type="hidden" name="transactionDate" value="${t.transactionDate||today()}" required></div><label class="field"><span>Catatan <small>(opsional)</small></span><input name="note" maxlength="120" value="${esc(t.note||'')}" placeholder="Tambahkan keterangan"></label>${footerButtons(item?'Simpan perubahan':'Simpan transaksi')}${item?'<button type="button" class="danger-button full" data-action="delete-tx" data-id="'+item.id+'">Hapus transaksi</button>':''}`,'transaction-sheet');if(item)$('#modal-form').dataset.editingId=item.id}
