if(a==='wallet-menu'){const w=accounts.find(x=>x.id===b.dataset.id);if(w&&confirm('Hapus dompet '+w.name+'?')){if(accounts.length<=1){toast('Sisakan minimal satu dompet. Tambahkan dompet lain sebelum menghapus yang ini.');return}if(transactions.some(t=>t.accountId===w.id||t.destinationAccountId===w.id)){toast('Dompet masih digunakan transaksi.');return}await remove('accounts',w.id);await refresh();toast('Dompet dihapus.')}}
if(a==='toggle-balance'){const n=$('#balance-value'),hide=n.dataset.hidden!=='true';n.dataset.hidden=String(hide);n.textContent=hide?'••••••••':money(sumSafeIntegers([...balances().values()],'Total saldo seluruh dompet'));b.textContent=hide?'◎':'◉'}
