if(a==='archive-category'||a==='restore-category'){const c=categories.find(x=>x.id===b.dataset.id);if(c){if(a==='archive-category'){const hasTransactions=transactions.some(t=>t.categoryId===c.id),hasBudgets=budgets.some(budget=>budget.categoryId===c.id);if((hasTransactions||hasBudgets)&&!confirm('Arsipkan kategori '+c.name+'? Transaksi lama tetap tersimpan. '+(hasBudgets?'Anggaran kategori ini akan disembunyikan dari statistik selama kategori diarsipkan dan muncul lagi jika dipulihkan.':'')))return;await put('categories',archiveCategory(c))}else await put('categories',restoreCategory(c));categories=await all('categories');$('#category-manage-list').innerHTML=categoryManageList($('.category-manage-tabs .selected')?.dataset.catType||'expense');toast(a==='archive-category'?'Kategori diarsipkan.':'Kategori dipulihkan.')}}
